import { Tabs, IconButton, Button, toast } from "march/ui"
import { plus, fileText } from "march/icons"

// bir editörün açık dosyaları: kaydedilmemiş olanda nokta, her sekmede kapatma işareti (Delete tuşu da kapatır),
// şeridin sonunda yeni dosya düğmesi; seçili sekme bind:value ile $active'te
interface OpenFile { id: string; name: string; text: string; dirty: boolean }

export function FileTabs() {
  let $files: OpenFile[] = [
    { id: "app", name: "App.tsx", text: "export function App() { return <Home /> }", dirty: false },
    { id: "router", name: "router.ts", text: "export const routes = { \"/\": Home, \"/ayarlar\": Settings }", dirty: true },
    { id: "theme", name: "theme.css", text: ":root { --m-radius-3: 12px; }", dirty: false },
  ]
  let $active = "app"
  let $count = 1
  const dirty = (id: string) => $files.find((f) => f.id === id)?.dirty ?? false
  const save = (id: string) => { $files = $files.map((f) => (f.id === id ? { ...f, dirty: false } : f)); toast("Kaydedildi") }
  const close = (id: string) => { $files = $files.filter((f) => f.id !== id) }
  const add = () => {
    const id = `yeni-${$count}`
    $files = [...$files, { id, name: `adsız-${$count}.ts`, text: "", dirty: true }]
    $count++
    $active = id
  }
  return <Tabs label="Açık dosyalar" bind:value={$active} onClose={close} labels={{ close: "Dosyayı kapat", dirty: "kaydedilmedi" }}
    actions={<IconButton icon={plus} label="Yeni dosya" size="sm" on:click={add} />}
    tabs={() => $files.map((f) => ({
      id: f.id, label: f.name, icon: fileText, closable: true, dirty: () => dirty(f.id),
      content: () => <div sx={{ flex: "col", gap: 2 }}>
        <code sx={{ text: "mono" }}>{f.text || "// boş dosya"}</code>
        {() => (dirty(f.id) ? <Button size="sm" on:click={() => save(f.id)}>Kaydet</Button> : <span sx={{ text: "sm", color: "muted" }}>Kaydedildi</span>)}
      </div>,
    }))} />
}

import { Tabs, Tab, IconButton } from "march/ui"
import { animate } from "march/motion"
import { home, users, creditCard, edit, eye } from "march/icons"

// Tabs'ın bütün özellikleri: tabs (id, label, badge, disabled, hidden, icon, title, closable, dirty, content), value,
// onChange, setValue (bind:value), query, class, children (<Tab>), panel, actions, indicator, motion (hazır ve kendi
// işlevin), label, variant, activation, onClose, closeIcon, labels (close, dirty), tabProps
export function TabsLab() {
  let $tab = "home"
  let $size = "md"
  let $team = 3
  let $showDraft = false
  let $closed: string[] = []
  // kendi panel hareketin: yeni sekme sağdaysa sağdan, soldaysa soldan büyüyerek gelir
  const swing = (panel: HTMLElement, dir: 1 | -1) => animate(panel, [{ opacity: 0, transform: `translateX(${dir * 16}px) scale(.96)` }, { opacity: 1, transform: "none" }], { duration: 240 })
  return <div sx={{ flex: "col", gap: 3 }}>
    <Tabs class="lab-tabs" label="Lab sekmeleri" value={$tab} onChange={(id: string) => $tab = id} activation="manual" motion="fade"
      onClose={(id: string) => $closed = [...$closed, id]} closeIcon="✕" labels={{ close: "Sekmeyi kapat", dirty: "kaydedilmedi" }}
      tabProps={(t: { id: string }) => ({ "data-lab": t.id })}
      actions={<IconButton icon={eye} label={$showDraft ? "Taslağı gizle" : "Taslağı göster"} size="sm" pressed={$showDraft} on:click={() => $showDraft = !$showDraft} />}
      tabs={[
        { id: "home", label: "Özet", icon: home, content: () => <p>Seçili: {$tab}</p> },
        { id: "team", label: "Ekip", icon: users, badge: () => $team, content: () => <p>Seçili: {$tab} · {$team} kişi</p> },
        { id: "billing", label: "Ödeme", icon: creditCard, disabled: true, title: "Planınızda yok", content: "Ödeme" },
        { id: "draft", label: "Taslak", icon: edit, hidden: () => !$showDraft || $closed.includes("draft"), closable: true, dirty: true, content: () => <p>Seçili: {$tab}</p> },
      ]} />
    <Tabs class="lab-tabs2" label="Boyut" variant="pill" indicator={false} panel={false} bind:value={$size} tabs={[
      { id: "sm", label: "Küçük" }, { id: "md", label: "Orta" }, { id: "lg", label: "Büyük" },
    ]} />
    <span sx={{ text: "sm", color: "muted" }}>Boyut: {$size}</span>
    <Tabs class="lab-tabs3" label="Alt çizgisiz" indicator={false} query="lab-sekme" motion={swing}>
      <Tab id="first" label="Birinci">Birinci panel</Tab>
      <Tab id="second" label="İkinci">İkinci panel</Tab>
      <Tab id="third" label="Üçüncü" title="Son sekme">Üçüncü panel</Tab>
    </Tabs>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { TabsLab } from "./TabsLab.tsx"

// TabsLab'in testleri: kaydedince Testler sekmesinde çalışır. Sekmeler tabProps'un verdiği data-lab ile bulunur
test("Ekip'e basınca seçilir, onChange paneli değiştirir; rozet sekmede", async () => {
  const s = renderTest(() => <TabsLab />)
  const team = s.get("[data-lab='team']")!
  await s.click(team)
  expect(team.getAttribute("aria-selected")).toBe("true")
  expect(team.textContent).toContain("3")
  expect(s.sees("Seçili: team · 3 kişi")).toBe(true)
})

test("disabled sekme kilitli ve nedenini title'da söyler", () => {
  const s = renderTest(() => <TabsLab />)
  const billing = s.get("[data-lab='billing']")
  expect(billing?.hasAttribute("disabled")).toBe(true)
  expect(billing?.getAttribute("title")).toBe("Planınızda yok")
})

test("hidden sekme eylemle gelir; değişti noktası adını taşır; kapatma işareti onClose'u çağırır", async () => {
  const s = renderTest(() => <TabsLab />)
  expect(s.get("[data-lab='draft']")).toBe(null)
  await s.click("Taslağı göster")
  expect(s.get("[data-lab='draft']")).not.toBe(null)
  expect(s.find("kaydedilmedi")).not.toBe(null)
  await s.click(s.get("[data-lab='draft'] .m-tab-close")!)
  expect(s.get("[data-lab='draft']")).toBe(null)
})

test("panel={false} yalnız şerit çizer, bind:value seçimi yazar; <Tab> çocukları sekme olur", async () => {
  const s = renderTest(() => <TabsLab />)
  expect(s.get(".lab-tabs2 [role='tabpanel']")).toBe(null)
  await s.click("Küçük")
  expect(s.sees("Boyut: sm")).toBe(true)
  expect(s.all(".lab-tabs3 [role='tab']").length).toBe(3)
  expect(s.find("Son sekme")?.textContent).toBe("Üçüncü")
})
